-- ============================================================
-- Women's and youth players, and what they did on the pitch.
--
-- The database held senior men only. These 337 players appear in the
-- team sheets the website ships for the women's and youth competitions and
-- nowhere in the CMS, which is why those competitions had squads of nobody
-- and no scorers.
--
-- Names needed resolving before anything could be keyed to them. The source
-- writes the same person more than one way — "Osman Abugre" and "Abugre
-- Osman", "Aseye A. Akuklu" and "Aseye Akuklu", some with a stray character
-- or a trailing full stop. Matching on the set of name parts rather than the
-- string collapsed 12 spellings onto 345 people. Without that
-- step each variant would have become its own player record.
--
-- Club is taken from the player's most recent appearance. Gender and grade
-- come from the competitions they played in: a women's or girls' competition
-- means female, any youth competition means youth. Four girls appear in both
-- the Youth Girls' championship and the Women's President's Cup — youth
-- players called into a representative side — and are recorded as youth.
--
-- They are marked inactive: none holds a 2026 registration. Being on record
-- is not the same as being registered this season.
--
-- Run AFTER womens_youth_seed.sql. Safe to re-run.
-- ============================================================

-- ── 1. Players ──────────────────────────────────────────────

drop table if exists _wy_players;

create temp table _wy_players (
  full_name  text,
  first_name text,
  last_name  text,
  club       text,
  gender     text,
  category   text
);


select p.first_name, p.last_name, t.team_id, p.gender, p.category, 'inactive'
from _wy_players p
left join teams t on t.name = p.club
where not exists (
  select 1 from players x
  where x.first_name = p.first_name and x.last_name = p.last_name
);

-- ── 2. Scoring events ───────────────────────────────────────
-- Matched to the fixture by competition, season, both teams and date rather
-- than by slug: youth and men's sides of the same clubs met on the same day,
-- so slugs are not unique to a competition.

drop table if exists _wy_events;

create temp table _wy_events (
  comp text, season text, home text, away text, dt date,
  team text, player_name text, event_type text, minute integer
);


select f.fixture_id, pl.player_id, tm.team_id, e.event_type, e.minute
from _wy_events e
join competitions c on c.name = e.comp and c.season = e.season
join teams h on h.name = e.home
join teams a on a.name = e.away
join fixtures f
  on f.competition_id = c.competition_id
 and f.home_team_id = h.team_id
 and f.away_team_id = a.team_id
 and f.scheduled_date = e.dt
join teams tm on tm.name = e.team
join players pl on pl.first_name || ' ' || pl.last_name = e.player_name
where not exists (
  select 1 from match_events x
  where x.fixture_id = f.fixture_id
    and x.player_id = pl.player_id
    and x.event_type = e.event_type
    and x.minute is not distinct from e.minute
);

-- ── 3. Line-ups ─────────────────────────────────────────────

drop table if exists _wy_lineups;

create temp table _wy_lineups (
  comp text, season text, home text, away text, dt date,
  team text, player_name text
);


select f.fixture_id, tm.team_id, pl.player_id, true
from _wy_lineups l
join competitions c on c.name = l.comp and c.season = l.season
join teams h on h.name = l.home
join teams a on a.name = l.away
join fixtures f
  on f.competition_id = c.competition_id
 and f.home_team_id = h.team_id
 and f.away_team_id = a.team_id
 and f.scheduled_date = l.dt
join teams tm on tm.name = l.team
join players pl on pl.first_name || ' ' || pl.last_name = l.player_name
on conflict (fixture_id, team_id, player_id) do nothing;

drop table _wy_players;
drop table _wy_events;
drop table _wy_lineups;
